void LoadedSessionWriterParticipant::DidAppWrite(
    size_t index, sessions::SessionWriteCompletion result) {
  CHECK(phase_ == Phase::kWriting);
  CHECK(pending_writes_ && !result_.profiles[index].app_session.write.has_value());
